import{_ as s,o as a,c as t,ai as e}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"库存并发扣减与防超卖","description":"","frontmatter":{},"headers":[],"relativePath":"scenarios/inventory-deduction.md","filePath":"scenarios/inventory-deduction.md"}'),l={name:"scenarios/inventory-deduction.md"};function d(n,i,r,h,o,k){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="库存并发扣减与防超卖" tabindex="-1">库存并发扣减与防超卖 <a class="header-anchor" href="#库存并发扣减与防超卖" aria-label="Permalink to “库存并发扣减与防超卖”">​</a></h1><blockquote><p>面向 WMS / 电商 / 票务的库存扣减：高并发下不超卖、余额与流水一致。关联实例：<a href="/my-vitepress-site/instances/industrial/wms.html">WMS 仓储管理</a>。</p></blockquote><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h2><ul><li>多人同时出库 / 下单，<code>stock</code> 被并发修改，出现<strong>超卖或负库存</strong>。</li><li>余额与流水对不上：扣了库存没落流水，或流水与余额不一致，无法对账。</li></ul><h2 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to “方案对比”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>悲观锁</td><td><code>select ... for update</code></td><td>简单、强一致</td><td>锁范围大、并发差</td></tr><tr><td>乐观锁</td><td><code>version</code> / CAS 条件更新</td><td>无锁、并发好</td><td>冲突需重试</td></tr><tr><td>分布式锁</td><td>Redis <code>SETNX</code></td><td>跨实例互斥</td><td>锁粒度 / 续期复杂</td></tr><tr><td>预扣 + 异步</td><td><code>reserved</code> 预占，MQ 异步落库</td><td>削峰、体验好</td><td>最终一致</td></tr></tbody></table><h2 id="推荐做法" tabindex="-1">推荐做法 <a class="header-anchor" href="#推荐做法" aria-label="Permalink to “推荐做法”">​</a></h2><ol><li>余额拆成 <code>total / reserved / available</code>，<code>available = total - reserved - locked</code>。</li><li>扣减用 <strong>CAS 条件更新</strong>，影响行数为 0 即失败（拒绝或重试）：</li></ol><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> wms_stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #{n}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #{sku} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> batch_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #{batch} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #{n};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ol start="3"><li>流水 <code>wms_stock_flow</code> <strong>只 append</strong>，不 update / delete，作为对账依据。</li><li>超高并发先用 Redis 预扣，再 MQ 异步落库（见 <a href="/my-vitepress-site/scenarios/seckill.html">秒杀系统架构</a>）。</li></ol><h2 id="取舍" tabindex="-1">取舍 <a class="header-anchor" href="#取舍" aria-label="Permalink to “取舍”">​</a></h2><ul><li>强一致优先 → 乐观锁 + 事务；吞吐优先 → 预扣 + 最终一致。</li><li>预扣会引入「超时释放」逻辑，复杂度上升。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2><ul><li><a href="/my-vitepress-site/scenarios/api-idempotent.html">接口幂等性设计</a>（重复提交导致重复扣减）</li><li><a href="/my-vitepress-site/scenarios/seckill.html">秒杀系统架构</a>（内存预扣 + 异步落库）</li><li>实例：<a href="/my-vitepress-site/instances/industrial/wms.html">WMS 仓储管理</a></li></ul><hr><p>上一级：<a href="/my-vitepress-site/scenarios/">解决方案总览</a></p>`,16)])])}const E=s(l,[["render",d]]);export{c as __pageData,E as default};
